{"command":"cd /workspace && python3 -c "
import json, ssl, urllib.request, re, os, sys
ca=open('/tmp/ca.pem').read()
server='https://benchmark-deprecated-api-group-01a340d6-control-plane:6443'
cfg=open(os.environ['HOME']+'/kube/config').read(); m=re.search(r'server:\s*(https://[^ ]+)',cfg); server=m.group(1) if m else 'server'
ctx=ssl.create_default_context(); ctx.load_verify_locations(ca)

containers=[{'name':'app','image':'nginx:1.31.5','ports':[{'name':'http','containerPort':80}]}]
template={'metadata':{'labels':{'app':'app'}},'spec':{'containers':containers}}
obj={'apiVersion':'apps/v1','kind':'Deployment','metadata':{'name':'app','labels':{'app':'app'}},'spec':{'replicas':3,'selector':{'matchLabels':{'app':'app'}}, 'template':template}}
body=json.dumps(obj).encode()

req=urllib.request.Request(f'{server}/apis/apps/v1/namespaces/legacy-app/deployments', data=body, headers={'Accept':'application/json','Content-Type':'application/json'})
for i in range(3):
    try: r=urllib.request.urlopen(req, context=ctx); print('OK:',r.status,r.read().decode())
        sys.exit()
    except urllib.error.HTTPError as e: 
        print('HTTP:',e.code,e.reason)
        open('/tmp/body.txt','wb').write(e.read()); print(open('/tmp/body.txt').read()[:1200]); sys.exit()
print('no error')
" 2>&1 | head -40"}

